WITH enriched AS (SELECT *, AVG(cost) OVER (PARTITION BY category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_cost, COUNT(cost) OVER (PARTITION BY category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_cost, MIN(cost) OVER (PARTITION BY category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_cost, ROUND(cost / SUM(cost) OVER (PARTITION BY supplier_id), 4) AS cost_share FROM products) SELECT DATE_TRUNC('YEAR', launch_date) AS year_start, APPROX_PERCENTILE(running_avg_cost, 0.5) AS running_avg_cost_p50, COUNT(*) AS row_count, AVG(running_min_cost) FILTER (WHERE category = 'Home') AS home_avg_running_min_cost, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN brand = 'Globex' THEN 1 END), 0), 2) AS cost_per_globex FROM enriched GROUP BY DATE_TRUNC('YEAR', launch_date)
